namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
    public bool IsRead { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications =
        [
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
            new() { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
            new() { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        ];
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            var newer = _notifications
                .Where(n => n.Id > lastId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally; in a real app this would come from a DB or message queue.
    /// </summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30% chance of a new notification each poll cycle
            if (Random.Shared.Next(100) < 30)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = $"Something happened at {DateTime.UtcNow:T}",
                    Timestamp = DateTime.UtcNow,
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge bg-primary ms-2">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? _notifications;
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Persisted { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (Persisted is not null)
        {
            // Restored from prerender — skip the fetch
            _notifications = Persisted;
        }
        else
        {
            _notifications = await Svc.GetNotificationsAsync();
            Persisted = _notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                Svc.SimulateIncoming();

                var lastId = _notifications?.Count > 0
                    ? _notifications.Max(n => n.Id)
                    : 0;

                var newer = await Svc.GetNotificationsSinceAsync(lastId);

                if (newer.Count > 0)
                {
                    _notifications = [..newer, ..(_notifications ?? [])];
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

